const SECRET = process.env.OUTREACH_CONFIRM_SECRET || '__REPLACE_ME__';
function b64urlDecode(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  const pad = s.length % 4 ? '='.repeat(4 - (s.length % 4)) : '';
  return Buffer.from(s + pad, 'base64').toString('utf8');
}
function sign(data) { return require('crypto').createHmac('sha256', SECRET).update(data).digest('hex'); }
const q = $json.query || $json.body || {};
const token = q.token || '';
if (!token) return [{ json: { ok: false, status: 401, error: 'Missing token' } }];
let payload;
try { payload = JSON.parse(b64urlDecode(token)); } catch (e) { return [{ json: { ok: false, status: 400, error: 'Bad token' } }]; }
const { itemId, exp, sig } = payload;
if (!itemId || !exp || !sig) return [{ json: { ok: false, status: 400, error: 'Token missing fields' } }];
if (Date.now() > Number(exp)) return [{ json: { ok: false, status: 410, error: 'Token expired' } }];
if (sign(String(itemId) + '|' + String(exp)) !== String(sig)) return [{ json: { ok: false, status: 401, error: 'Invalid signature' } }];
return [{ json: { ok: true, itemId: String(itemId), status: 200, token } }];

